eAssets(                svg: AppImagesSvg.cardOffersCarpenters,                width: 359.w,              ),              Positioned(                right: 50.w,                height: 180.h,                child: BuildImageAssets(                  png: AppImagesPng.carpenter,                ),              ),              Positioned(                left: 25.w,                bottom: 50.h,                child: Text("40% Off",                    style: AppTextStyles.h3Bold.copyWith(                      color: AppColors.textColorWhite,                    )),              ),              Positioned(                left: 25.w,                bottom: 35.h,                child: Text(                  "On First Carpenter Service",                  style: AppTextStyles.bodyMediumMedium.copyWith(                    color: AppColors.textColorWhite,                  ),                ),              ),            ],          ),        ),        SliverFillRemaining(          child: Align(            child: BuildSocialLoginButton(text: "Proceed", backgroundColor: AppColors.primaryColor, onPressed: (){},              isSpace: false,            ),          ),        )      ].styledAppPages(withScaffold: true, withPadding: true),    );  }}class CustomAppBarServices extends StatelessWidget    implements PreferredSizeWidget {  const CustomAppBarServices({super.key});  @override  Widget build(BuildContext context) {    return AppBar(      toolbarHeight: 100.h,      backgroundColor: AppColors.secondaryColor,      leading: IconButton(        icon: Icon(Icons.arrow_back, color: Colors.white),        onPressed: () => kNavigationService.goBack(),      ),      title: Text(        "Carpenter Service",        style: AppTextStyles.h4Bold.copyWith(color: AppColors.textColorWhite),      ),      centerTitle: true,      flexibleSpace: Align(        alignment: Alignment.bottomCenter,        child: Container(          height: 50,  